import java.util.Arrays;
import java.util.Scanner;

public class LuckyTickets {
    private static final int MOD = 998244353;
    private static final int ROOT = 15311432;
    private static final int INVROOT = 469870224;

    private static int reverseBits(int n, int k) {
        return Integer.reverse(n) >>> (32 - k);
    }

    private static long computeModInverse(int a) {
        return computeModPow(a, MOD - 2);
    }

    private static long computeModPow(int base, int exponent) {
        long result = 1;
        long b = base;
        while (exponent > 0) {
            if ((exponent & 1) == 1) {
                result = (result * b) % MOD;
            }
            b = (b * b) % MOD;
            exponent >>= 1;
        }
        return result;
    }

    private static void performFFT(long[] array, int logN, boolean inverse) {
        int baseRoot = inverse ? INVROOT : ROOT;
        long root = computeModPow(baseRoot, (int) Math.pow(2, 23 - logN));
        long[] roots = new long[logN];
        roots[logN - 1] = root;
        for (int i = logN - 1; i > 0; i--) {
            roots[i - 1] = (roots[i] * roots[i]) % MOD;
        }
        for (int s = 0; s < logN; s++) {
            int segmentSize = 1 << s;
            for (int startIdx = 0; startIdx < array.length; startIdx += 2 * segmentSize) {
                long currentRoot = 1;
                for (int j = startIdx; j < startIdx + segmentSize; j++) {
                    long t = (currentRoot * array[j + segmentSize]) % MOD;
                    long u = array[j];
                    array[j] = (u + t) % MOD;
                    array[j + segmentSize] = (u - t) % MOD;
                    currentRoot = (roots[s] * currentRoot) % MOD;
                }
            }
        }
    }

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int n = sc.nextInt() / 2;
        int m = sc.nextInt();
        int[] nums = new int[m];
        for (int i = 0; i < m; i++) {
            nums[i] = sc.nextInt();
        }
        Arrays.sort(nums);
        int minSize = n * nums[m - 1] + 2;
        int logSize = 0;
        int size = 1;
        while (size < minSize) {
            size <<= 1;
            logSize++;
        }
        long[] array = new long[size];
        for (int num : nums) {
            array[reverseBits(num, logSize)] = 1;
        }
        performFFT(array, logSize, false);
        for (int i = 0; i < size; i++) {
            array[i] = computeModPow((int) array[i], n);
        }
        long[] tempArray = new long[size];
        for (int i = 0; i < size; i++) {
            tempArray[reverseBits(i, logSize)] = array[i] % MOD;
        }
        array = tempArray;
        performFFT(array, logSize, true);
        long totalSumSquares = 0;
        for (int i = 0; i < size; i++) {
            totalSumSquares = (totalSumSquares + array[i] * array[i]) % MOD;
        }
        long invSize = computeModInverse(size);
        System.out.println((((totalSumSquares * invSize) % MOD) * invSize) % MOD);
    }
}
